import{_ as L,l as i,o as e,c as l,v as a,p as o,x as r,d as B,i as V,S as s}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"InternVL / InternVL2","description":"","frontmatter":{"title":"InternVL / InternVL2","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/internvl-paper.md","filePath":"llm/internvl-paper.md","lastUpdated":1789023840000}'),p={name:"llm/internvl-paper.md"};function I(A,n,h,m,d,E){const t=i("Mermaid");return e(),l("div",null,[n[1]||(n[1]=a('<h1 id="internvl-internvl2" tabindex="-1">InternVL / InternVL2 <a class="header-anchor" href="#internvl-internvl2" aria-label="Permalink to &quot;InternVL / InternVL2&quot;">​</a></h1><div class="epigraph"><p>先把视觉基础模型做到 6B 并可迁移，再按长宽比切 448 格把分辨率变成上下文；2.0 把同一套管线接到从端侧到 70B 的多种 LLM。</p><footer>—— Chen 等，InternVL，CVPR 2024；OpenGVLab InternVL 2.0</footer></div><p>上海人工智能实验室 OpenGVLab 的 InternVL 线要回答的，不是又一个聊天投影器，而是：<strong>视觉塔能否做成像 LLM 那样可复用的基础模型</strong>。2023 年末的 InternVL 1.0（Chen 等，arXiv:2312.14238，CVPR 2024）把 InternViT-6B 与语言中间件 QLLaMA 对齐到网页级图文，覆盖分类、检索、对话等 32 项通用视觉–语言基准，并主张可替代当时的 ViT-22B 级视觉塔。2024 年 4 月的 InternVL 1.5（<em>How Far Are We to GPT-4V?</em>，arXiv:2404.16821）加上持续学习、动态高分辨率与中英双语数据。2024 年 7 月的 <strong>InternVL2</strong> 没有单独长篇 arXiv，而是把 1.5 的切块配方接到 1B–76B 多档 LLM。2.0 规格见 <a href="/llm/internvl2">InternVL2</a>；本篇写 1.0 / 1.5 原文与 2.0 如何坐在它们上面，不把 2.5 / 3 的编码器升级倒填。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>2023 年 LLM 已经到 10B–70B，开源视觉编码器仍停在百兆到 1B 量级的 CLIP 变体。多模态 AGI 缺的是能跟上语言容量的视觉基础模型：要能做像素级感知，也要能接到现成 LLM 上对话。轻量 Q-Former 或线性层当胶水，参数太少，冻住 LLM 时对话上不去；完全端到端重训又浪费已有语言权重。InternVL 1.0 的问题是：能否把 ViT 做到 6B，再用一个<strong>足够大</strong>的语言中间件做对齐，使视觉特征空间与现成 LLM 一致，从而分类、检索、生成共用一座视觉塔。</p><p>1.5 面对的产品缺口更具体：开源模型文档 OCR 掉字、中文弱、分辨率锁在 224/336。需要在不重做 6B 塔的前提下，把输入抬到 4K 量级，并用双语问答把 OCR 与中文拉上来。2.0 的缺口则是部署谱：同一套切块能否覆盖端侧 1B 与云端 70B。</p><h3 id="_6b-视觉塔加-8b-中间件-而不是一层-mlp" tabindex="-1">6B 视觉塔加 8B 中间件，而不是一层 MLP <a class="header-anchor" href="#_6b-视觉塔加-8b-中间件-而不是一层-mlp" aria-label="Permalink to &quot;6B 视觉塔加 8B 中间件，而不是一层 MLP&quot;">​</a></h3><p>InternViT-6B 是为性能–效率折中定制的 ViT。QLLaMA 约 8B，从多语增强 LLaMA（Cui 等）初始化，新加 96 个可学习 query 与交叉注意力（约 1B 随机初始化）。相对 Q-Former，中间件大四十倍量级，且自带多语文本表示：既能做图文对比学习（InternVL-C / InternVL-G 两种推理），也能当生成式前缀做字幕，还能冻住 Vicuna / InternLM 只训 MLP 就做对话。这是 1.0 相对「CLIP + 线性层」的结构差。</p><p><span class="marginnote">QLLaMA 不是用户推理时必须跑的 8B 聊天模型。对话形态里它是胶水：视觉 token 经它对齐后再进 Vicuna。1.5 / 2.0 文档主路径改成 InternViT + 像素重排 + 两层 MLP + LLM，中间件配方被更轻的投影取代，但 6B 塔的可迁移性是 1.0 训出来的。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>1.0 分阶段。对比学习阶段用约 49.8 亿级图文把 InternViT 拉成视觉基础模型。生成阶段把 InternViT 与 QLLaMA 冻住，只训新 query 与交叉注意力，数据滤到约 10.3 亿高质量字幕，损失为 ITC + ITM + ITG（BLIP-2 同类）。对话阶段经 MLP 接 Vicuna-7B/13B 等，约 400 万指令；因特征空间已接近 LLM，可冻解码器只训 MLP，或解冻 QLLaMA。对比推理：InternVL-C 用 ViT 侧全局特征，InternVL-G 用 QLLaMA query 特征，文本取 QLLaMA 的 [EOS]。</p><h3 id="_1-5-的三条改进与-2-0-的多底座复制" tabindex="-1">1.5 的三条改进与 2.0 的多底座复制 <a class="header-anchor" href="#_1-5-的三条改进与-2-0-的多底座复制" aria-label="Permalink to &quot;1.5 的三条改进与 2.0 的多底座复制&quot;">​</a></h3><p>1.5 三条：(1) 对 InternViT-6B 持续学习，使同一塔可接到不同 LLM；(2) <strong>动态高分辨率</strong>：按长宽比把图切成 1 到 40 个 \\(448\\times 448\\) 格，训练最多约 12 格，测试可到 40 格（文档称 4K）；(3) 高质量中英双语数据，覆盖自然图与文档，显著抬 OCR 与中文。像素重排把每格 1024 patch 收到 256 token。2.0 把这一配方复制到多语言骨干：小档 InternViT-300M + Qwen2 / InternLM / Phi-3；26B 及以上接 InternViT-6B-V1-5 + InternLM-20B / Yi-34B / Llama-3-70B 系。各档表见 InternVL2 专文。2.0 没有新的视觉定律，也没有 2024 年 7 月的独立 arXiv。</p>',13)),(e(),o(s,null,{default:r(()=>[V(t,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20v10%20%5B%22InternVL%201.0%22%5D%0A%20%20%20%20V6%5B%22InternViT-6B%22%5D%20--%3E%20QL%5B%22QLLaMA%20%E4%B8%AD%E9%97%B4%E4%BB%B6%22%5D%0A%20%20%20%20QL%20--%3E%20CTR%5B%22%E5%AF%B9%E6%AF%94%EF%BC%9A%E5%88%86%E7%B1%BB%20%2F%20%E6%A3%80%E7%B4%A2%22%5D%0A%20%20%20%20QL%20--%3E%20GEN%5B%22%E7%94%9F%E6%88%90%EF%BC%9A%E5%AD%97%E5%B9%95%22%5D%0A%20%20%20%20QL%20--%3E%20MLP%5B%22MLP%22%5D%0A%20%20%20%20MLP%20--%3E%20LLM1%5B%22Vicuna%20%2F%20InternLM%22%5D%0A%20%20end%0A%20%20subgraph%20v15%20%5B%221.5%20%2F%202.0%22%5D%0A%20%20%20%20TILE%5B%22%E5%8A%A8%E6%80%81%20448%20%E5%88%87%E5%9D%97%22%5D%20--%3E%20VIT%5B%22InternViT%20300M%20%E6%88%96%206B%22%5D%0A%20%20%20%20VIT%20--%3E%20PS%5B%22%E5%83%8F%E7%B4%A0%E9%87%8D%E6%8E%92%20%E6%AF%8F%E6%A0%BC%20256%20token%22%5D%0A%20%20%20%20PS%20--%3E%20MLP2%5B%22MLP%22%5D%0A%20%20%20%20MLP2%20--%3E%20LLM2%5B%22%E5%A4%9A%E6%A1%A3%E5%BC%80%E6%BA%90%20LLM%22%5D%0A%20%20end%0A%20%20V6%20-.-%3E%7C%22%E6%8C%81%E7%BB%AD%E5%AD%A6%E4%B9%A0%E5%8F%AF%E8%BF%81%E7%A7%BB%22%7C%20VIT%0A"})]),fallback:r(()=>[...n[0]||(n[0]=[B(" Loading... ",-1)])]),_:1})),n[2]||(n[2]=a('<p><span class="marginnote">测试期 40 格是延迟旋钮，不是训练见过 40 格的保证。服务必须按最坏格数预留 KV。BNB 4-bit 量化在 InternViT-6B 上官方不建议：视觉侧误差会让模型「看不见」。博客里的 InternVL2-108B 与文档主表 1B–76B 不要混成同一天下载集合。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>1.0 的机制是<strong>表示对齐先于对话</strong>。6B ViT 先在对比目标上学会可检索的视觉空间；QLLaMA 用 LLM 初始化的语言空间去读这些视觉 token，所以后续接 Vicuna 时特征已经在附近，冻 LLM 仍能对话。这与 LLaVA 式「随机投影 + 全参 SFT」相反：InternVL 把贵的对齐算力花在中间件和视觉塔上，聊天只是最后一跳。1.5 的切块机制与 AnyRes 同类：编码器权重与 448 边长不变，细字靠更多原生窗口；像素重排是格内压缩，信息仍在，LLM 看到的是下采样网格。持续学习让 6B 塔在换 LLM 时不必从 CLIP 再训一遍。</p><p>2.0 换语言骨干不等于换视觉能力。300M 与 6B 编码器的表示密度不同：小档能跑在端侧，文档上限仍受视觉塔约束；76B 档的增益大量来自 70B 级世界知识。OpenCompass 一类综合分把两者混在一起，不能单独证明「切块算法赢了」。中英双语是 1.5 的数据主张，2.0 继承；小语种 OCR 没有同等保证。</p><h3 id="和-qwen-vl、paligemma-的分辨率合同不同" tabindex="-1">和 Qwen-VL、PaliGemma 的分辨率合同不同 <a class="header-anchor" href="#和-qwen-vl、paligemma-的分辨率合同不同" aria-label="Permalink to &quot;和 Qwen-VL、PaliGemma 的分辨率合同不同&quot;">​</a></h3><p>Qwen2-VL 的原生动态分辨率按原图像素切 patch，不一定先缩进 448 格。<a href="/llm/paligemma">PaliGemma</a> 把图缩到固定 224/448/896 方图，token 数固定。InternVL 对「已经有固定 448 的 InternViT」最友好。三者都叫动态或高分辨率，掩码、位置编码和账单不能互换。1.0 的 QLLaMA 对比学习能力（零样本分类 / 多语检索）在 2.0 聊天模型卡片上不再是主指标，不要用 2.0 对话分回溯 1.0 的 CLIP 式 SOTA。</p><p><span class="marginnote">引用只使用真实出处：1.0 为 Chen 等 arXiv:2312.14238；1.5 为 Chen 等 arXiv:2404.16821；2.0 以 OpenGVLab 2024-07-02 博客与 internvl2.0 文档为准。2.5 报告 arXiv:2412.05271 可用来核对 2.0 回溯表，但其编码器 V2.5 不属于 2.0。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>1.0 主分辨率 224/336，不能承担 1.5 的文档主张。1.5 / 2.0 的 40 格会先吃光 7B 档的 4K–8K 上下文。多图、视频不是 2.0 的主叙事。语言底座许可各异：Qwen2、InternLM、Phi、Llama 3、Yi 衍生叠加，再分发前要逐档读模型卡。聊天模板必须用对应底座的特殊符号。</p><p>不要给 InternVL2 编造独立的 2024 年 7 月 arXiv。不要把 2.5-Pro 或 InternVL3 的测试时缩放写进这一代。评测应分自然图、文档、图表三张表。1.0 的 32 项基准含感知与检索，与 2.0 的综合对话榜不是同一张图。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>InternVL 1.0 用 InternViT-6B + QLLaMA 做可迁移视觉基础模型，对比 / 生成 / 对话共用一塔。</li><li>InternVL 1.5 用持续学习、448 动态切块与双语数据追商业多模态；2.0 把该配方接到 1B–76B 多 LLM。</li><li>2.0 以博客与文档为出处；切块账单与量化限制见 InternVL2 专文。</li><li>出处：Chen 等，<em>InternVL</em>，arXiv:2312.14238；Chen 等，<em>How Far Are We to GPT-4V?</em>，arXiv:2404.16821；OpenGVLab InternVL 2.0，2024-07。</li></ul>',12))])}const T=L(p,[["render",I]]);export{P as __pageData,T as default};
